mapper.select:
SELECT price_id, security_id, price_date, low_price, high_price, open_price, close_price,
       daily_return_rate, trading_volume, trading_value, created_at
FROM security_daily_prices
WHERE security_id = #{securityId}
  AND price_date  = #{priceDate}

